/*!
 * wega-music-boss.js - WEGA FACE boss fight add-on for the Wega's Challenge music pack.
 * Load AFTER wega-music.js and BEFORE the game module. It registers a "boss" track with
 * WegaMusic so WegaMusic.init() decodes it with the others and WegaMusic.play("boss") works.
 * Track: Pizza Tower OST - Unexpectancy (Parts 1-3, final boss) - supplied by the player.
 * The fight plays it in layers (Music.syncBoss in index.html): each phase loops its own part until the next
 * phase starts, and the finale plays once the boss is down. `parts` says where each part starts and which bars
 * it loops (measured from the audio: 200 BPM, loops cut where the music repeats, nudged to click-free samples).
 */
(function (global) {
  "use strict";
  var D = global.WEGA_MUSIC_DATA, W = global.WegaMusic;
  if (!D || !W) { if (global.console) console.warn("[wega-music-boss] load wega-music.js first"); return; }
  D.boss = {
    title: "Unexpectancy (WEGA FACE Theme)",
    credit: "Pizza Tower OST - Unexpectancy, Parts 1-3",
    duration: 565.32,
    loopStart: 0.05,
    loopEnd: 565.02,
    gain: 0.85,
    parts: [
      { name: "PART 1", start: 0.05, loop: [27.35043, 70.55279] },        // phase 1: WEGA FACE
      { name: "PART 2", start: 120.25, loop: [178.54764, 260.14556] },    // phase 2: WEGA MAN
      { name: "PART 3", start: 284.45, loop: [333.89803, 420.29841] },    // phase 3: THE GAUNTLET
      { name: "FINALE", start: 497.99671, loop: [497.99671, 543.59707] }, // down: the exit is free
    ],
    src: "data:audio/mpeg;base64,"
  };
  if (W.tracks.indexOf("boss") < 0) W.tracks.push("boss");
})(typeof window !== "undefined" ? window : globalThis);
